<?php

# @autogenerated
declare(strict_types=1);

use Civi\Lughauth\Features\Notification\SmtpOutboundConfig\Domain\ValueObject\Accessor\SmtpOutboundConfigMaxRetriesAccessor;
use PHPUnit\Framework\TestCase;

/**
 * Unit tests for the SmtpOutboundConfigMaxRetriesAccessor trait.
 *
 * Covers null default, string/VO assignment via withMaxRetries,
 * getMaxRetries/maxRetries accessors, and isMaxRetriesChanged with/without original.
 */
class SmtpOutboundConfigMaxRetriesAccessorUnitTest extends TestCase
{
    /**
     * Asserts that withMaxRetries creates a new instance with the MaxRetries set
     * from a string value, and getMaxRetries returns the primitive string.
     */
    public function testWithMaxRetriesFromString(): void
    {
        // Arrange
        $holder = new ImplWithSmtpOutboundConfigMaxRetriesAccessorUnitTest();

        // Act
        $result = $holder->withMaxRetries(1);

        // Assert
        $this->assertNotSame($holder, $result);
        $this->assertEquals(1, $result->getMaxRetries());
    }
    /**
     * Asserts that withmaxRetries has access to the value object
     * from a string value, and getMaxRetries returns the primitive string.
     */
    public function testWithMaxRetriesFromValueObject(): void
    {
        // Arrange
        $holder = new ImplWithSmtpOutboundConfigMaxRetriesAccessorUnitTest();

        // Act
        $result = $holder->withMaxRetries(1);

        // Assert
        $this->assertNotSame($holder, $result);
        $this->assertEquals(1, $result->maxRetries()->value());
    }
    public function testChangedMaxRetries(): void
    {
        // Arrange
        $holder = new ImplWithSmtpOutboundConfigMaxRetriesAccessorUnitTest()->withMaxRetries(1);
        $original = $holder->withMaxRetries( 1);
        $same = $holder->withMaxRetries( 1);
        $modified = $holder->withMaxRetries(2);

        // Act
        $withSame = $original->isMaxRetriesChanged( $same );
        $withDiferent = $original->isMaxRetriesChanged( $modified );

        // Assert
        $this->assertFalse($withSame);
        $this->assertTrue($withDiferent);
    }
}
class ImplWithSmtpOutboundConfigMaxRetriesAccessorUnitTest
{
  use SmtpOutboundConfigMaxRetriesAccessor;
}
